1	import {
2	  CommonActions,
3	  createNavigationContainerRef,
4	} from "@react-navigation/native";
5	import { createNativeStackNavigator } from "@react-navigation/native-stack";
6	
7	// One native stack, with the menu as its root — conceptually the menu sits to
8	// the LEFT of the capture page. The app boots with Capture pushed on top of
9	// Menu (see initialState in App.tsx), so the native left-edge swipe-back on
10	// the capture page reveals the menu, and every other screen is pushed from the
11	// menu so swipe-back walks naturally back to it. From the menu, a right-edge
12	// leftward swipe or the close button pushes a fresh capture page back in.
13	export type RootStackParamList = {
14	  Menu: undefined;
15	  Capture: undefined;
16	  Feed: undefined;
17	  Folder: { path: string; title: string };
18	  Editor: { path: string; title?: string };
19	  Sync: undefined;
20	  Settings: undefined;
21	  SettingsWorkingFolders: undefined;
22	  SettingsTranscription: undefined;
23	};
24	
25	export const Stack = createNativeStackNavigator<RootStackParamList>();
26	
27	/** Container ref so deep-link handling can navigate from outside React. */
28	export const navigationRef = createNavigationContainerRef<RootStackParamList>();
29	
30	export const navigateToScreen = <Screen extends keyof RootStackParamList>(
31	  screen: Screen,
32	  params?: RootStackParamList[Screen]
33	) => {
