37	import { ToolbarButton } from "../ui/toolbar-button";
38	import { NoteListRow } from "./feed-screen";
39	
40	type MenuTab = "feed" | "folders";
41	
42	const RIGHT_EDGE_SWIPE_WIDTH = 56;
43	
44	export const MenuScreen = () => {
45	  const theme = useTheme();
46	  const insets = useSafeAreaInsets();
47	  const navigation =
48	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
49	  const [tab, setTab] = useState<MenuTab>("feed");
50	
51	  const tree = useNotesStore((s) => s.tree);
52	  const previews = useNotesStore((s) => s.previews);
53	
54	  const openScreen = <Screen extends keyof RootStackParamList>(
55	    screen: Screen,
56	    params?: RootStackParamList[Screen]
57	  ) => {
58	    navigation.dispatch(CommonActions.navigate({ name: screen, params }));
59	  };
60	
61	  const openCapture = () => navigation.navigate("Capture");
62	  const swipeToCapture = Gesture.Pan()
63	    .hitSlop({ right: 0, width: RIGHT_EDGE_SWIPE_WIDTH })
64	    .activeOffsetX(-24)
65	    .failOffsetX(24)
66	    .failOffsetY([-24, 24])
67	    .onStart(() => {
68	      runOnJS(openCapture)();
69	    });
70	
71	  const lastSyncedMs = useSyncStore((s) => s.history[0]?.authored_ms ?? null);
72	
73	  // Boot pushes Capture on top of the menu in the same first React commit,
74	  // so building the note/folder lists here would sit on the app's
75	  // first-paint path. Render an empty page for the first tick and fill in
76	  // right after — done long before a swipe can reveal the menu.
77	  const [contentReady, setContentReady] = useState(false);
78	  useEffect(() => {
79	    const task = InteractionManager.runAfterInteractions(() => setContentReady(true));
80	    return () => task.cancel();
81	  }, []);
82	  if (!contentReady) {
83	    return <View style={[styles.root, { backgroundColor: theme.colors.background }]} />;
84	  }
85	
86	  const feedRows = folderNoteRows(findFolder(tree, FEED_FOLDER_PATH), previews);
87	  const feedSections = groupNoteRowsByDate(feedRows);
88	  const folders = browsableFolders(findFolder(tree, ""));
89	
90	  return (
91	    <GestureDetector gesture={swipeToCapture}>
92	      <View
93	        style={[
94	          styles.root,
95	          {
96	            backgroundColor: theme.colors.background,
97	            paddingTop: insets.top + 8,
98	            paddingBottom: insets.bottom + 8,
99	          },
100	        ]}
101	      >
102	        {/* Mirrors the capture page's hamburger: same spot, same size. */}
103	        <View style={styles.topBar}>
104	          <ToolbarButton icon="close-outline" onPress={openCapture} />
105	        </View>
106	
107	        <View style={[styles.tabs, { backgroundColor: theme.colors.surface }]}>
108	          <TabButton label="Feed" active={tab === "feed"} onPress={() => setTab("feed")} />
109	          <TabButton
110	            label="Folders"
111	            active={tab === "folders"}
112	            onPress={() => setTab("folders")}
113	          />
114	        </View>
115	
116	        {tab === "feed" ? (
117	          <SectionList
118	            style={styles.list}
119	            sections={feedSections}
120	            keyExtractor={(row) => row.path}
121	            stickySectionHeadersEnabled
122	            renderSectionHeader={({ section }) => (
123	              <View style={[styles.sectionHeader, { backgroundColor: theme.colors.background }]}>
124	                <Text style={[styles.sectionHeaderText, { color: theme.colors.secondaryText }]}>
125	                  {section.title}
126	                </Text>
127	              </View>
128	            )}
129	            renderItem={({ item }) => (
130	              <NoteListRow
131	                row={item}
132	                theme={theme}
133	                onPress={() =>
134	                  openScreen("Editor", {
135	                    path: item.path,
136	                    title: item.preview.title || "Note",
137	                  })
138	                }
139	              />
140	            )}
141	            ListEmptyComponent={
142	              <Text style={[styles.empty, { color: theme.colors.secondaryText }]}>
143	                No notes yet — swipe left and start typing.
144	              </Text>
145	            }
146	          />
147	        ) : (
148	          <FlatList
149	            style={styles.list}
150	            data={folders}
151	            keyExtractor={(folder) => folder.path}
152	            renderItem={({ item }) => (
153	              <Pressable
154	                onPress={() => openScreen("Folder", { path: item.path, title: item.name })}
155	                style={({ pressed }) => [
156	                  styles.folderRow,
157	                  { borderBottomColor: theme.colors.border, opacity: pressed ? 0.6 : 1 },
158	                ]}
159	              >
160	                <Text style={[styles.folderName, { color: theme.colors.text }]}>
161	                  {item.name}
162	                </Text>
163	                <Text style={[styles.folderMeta, { color: theme.colors.secondaryText }]}>
164	                  {item.notes.length > 0 ? `${item.notes.length}` : ""} ›
165	                </Text>
166	              </Pressable>
167	            )}
168	            ListEmptyComponent={
169	              <Text style={[styles.empty, { color: theme.colors.secondaryText }]}>
170	                No folders yet.
171	              </Text>
172	            }
173	          />
