export const DictationButton = ({
  onRecordingChange,
}: {
  onRecordingChange?: (recording: boolean) => void;
}) => {
  const theme = useTheme();
  const recorder = useAudioRecorder(RecordingPresets.HIGH_QUALITY);
  const recorderState = useAudioRecorderState(recorder);

  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<PillStatus | null>(null);
  const statusTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Start is async (permission prompt, prepare) — a hold can end before it
  // finishes, so stopAndSave awaits the in-flight start before stopping.
  const startPromise = useRef<Promise<void> | null>(null);
  const pressInAt = useRef(0);
  const pressStartedRecording = useRef(false);

  const snapshot = useSettingsStore((s) => s.snapshot);
  const settings = activeProfile(snapshot)?.settings;
  const mode: TranscriptionMode = settings
    ? effectiveTranscriptionMode(settings)
    : "desktop";

  useEffect(() => {
    onRecordingChange?.(recorderState.isRecording);
  }, [recorderState.isRecording, onRecordingChange]);

  const showStatus = (next: PillStatus) => {
    if (statusTimer.current) {
      clearTimeout(statusTimer.current);
    }
    setStatus(next);
    statusTimer.current = setTimeout(() => setStatus(null), STATUS_VISIBLE_MS);
  };
  useEffect(
    () => () => {
      if (statusTimer.current) {
        clearTimeout(statusTimer.current);
      }
    },
    []
  );

  const start = async () => {
    const permission = await AudioModule.requestRecordingPermissionsAsync();
    if (!permission.granted) {
      throw new Error("Microphone permission denied — enable it in system settings.");
    }
    await setAudioModeAsync({ allowsRecording: true, playsInSilentMode: true });
    await recorder.prepareToRecordAsync();
    recorder.record();
  };

  const stopAndSave = async () => {
    setBusy(true);
    try {
      await startPromise.current;
      await recorder.stop();
      const uri = recorder.uri;
      if (!uri) {
        throw new Error("Recorder produced no file.");
      }
      const audioBase64 = await FileSystem.readAsStringAsync(uri, {
        encoding: "base64",
      });
      await core.saveAudioRecording({
        audio_base64: audioBase64,
        mime_type: "audio/mp4",
      });

      let detail = MODE_SAVED_DETAIL[mode];
      if (mode === "assemblyai") {
        try {
          await core.queueRecordingTranscriptions();
        } catch (queueError) {
          detail = `Saved, but queueing failed: ${getErrorMessage(queueError)}`;
        }
      } else if (mode === "native") {
        try {
          await core.queueProviderTranscriptions(nativeTranscriptionProvider);
        } catch (queueError) {
          detail = `Saved, but queueing failed: ${getErrorMessage(queueError)}`;
        }
      }
      showStatus({ kind: "success", text: detail });
      void useNotesStore.getState().refresh();
    } catch (err) {
      showStatus({ kind: "error", text: getErrorMessage(err) });
    } finally {
      startPromise.current = null;
      setBusy(false);
      // Leave the play-and-record session so playback routes normally again.
      void setAudioModeAsync({ allowsRecording: false, playsInSilentMode: true }).catch(
        () => {}
      );
    }
  };

  // Keep the latest stopAndSave reachable from the unmount effect below.
  const stopAndSaveRef = useRef(stopAndSave);
  stopAndSaveRef.current = stopAndSave;
  const recordingRef = useRef(false);
  recordingRef.current = recorderState.isRecording;

  // Best effort: navigating away (the capture page pops) while recording
  // stops and saves the clip instead of silently dropping it.
  useEffect(
    () => () => {
      if (recordingRef.current) {
        void stopAndSaveRef.current().catch(() => {});
      }
    },
    []
  );

  // The handlers read recorder.isRecording (a live native property) instead
  // of recorderState, which only re-polls every ~500ms — a quick tap-then-
  // release would otherwise see stale state.
  const onPressIn = () => {
    if (busy) {
      return;
    }
    pressInAt.current = Date.now();
    if (recorder.isRecording || startPromise.current) {
      pressStartedRecording.current = false;
      return;
    }
    pressStartedRecording.current = true;
    setStatus(null);
    startPromise.current = start().catch((err) => {
      startPromise.current = null;
      pressStartedRecording.current = false;
      showStatus({ kind: "error", text: getErrorMessage(err) });
    });
  };

  const onPressOut = () => {
    // Only an actual recording can be stopped; if start() is still in flight
    // (e.g. the first-use permission prompt interrupted the hold), releasing
    // leaves the recording running once it starts — the next tap stops it.
    if (busy || !recorder.isRecording) {
      return;
    }
    const held = Date.now() - pressInAt.current;
    if (pressStartedRecording.current && held < HOLD_TO_RECORD_MS) {
      // Quick tap: recording keeps running until the next tap.
      return;
    }
    void stopAndSave();
  };

  const seconds = Math.floor((recorderState.durationMillis ?? 0) / 1000);
  const timer = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;

  return (
    <View style={styles.root} pointerEvents="box-none">
      {recorderState.isRecording ? (
        <View style={[styles.pill, { backgroundColor: theme.colors.surface, borderColor: theme.colors.border }]}>
          <View style={[styles.recordingDot, { backgroundColor: theme.colors.danger }]} />
          <Text style={[styles.pillText, { color: theme.colors.text }]}>{timer}</Text>
        </View>
      ) : status ? (
        <View style={[styles.pill, { backgroundColor: theme.colors.surface, borderColor: theme.colors.border }]}>
          <Text
            style={[
              styles.pillText,
              { color: status.kind === "error" ? theme.colors.danger : theme.colors.secondaryText },
            ]}
            numberOfLines={2}
          >
            {status.text}
          </Text>
        </View>
      ) : null}
      {/* Same neutral circle as the toolbar buttons; only the icon signals
          the recording state. */}
      <Pressable
        onPressIn={onPressIn}
        onPressOut={onPressOut}
        disabled={busy}
        hitSlop={10}
        style={({ pressed }) => [
          styles.fab,
          {
            backgroundColor: theme.colors.surface,
            borderColor: theme.colors.border,
            opacity: busy ? 0.5 : pressed ? 0.6 : 1,
            transform: [{ scale: pressed ? 0.94 : 1 }],
          },
        ]}
      >
        <Ionicons
          name={recorderState.isRecording ? "stop" : "mic-outline"}
          size={22}
          color={recorderState.isRecording ? theme.colors.danger : theme.colors.text}
        />
      </Pressable>
    </View>
  );
};

const styles = StyleSheet.create({
  root: { alignItems: "flex-end", gap: 10 },
  pill: {
    flexDirection: "row",
    alignItems: "center",
    gap: 6,
    maxWidth: 260,
    borderRadius: 16,
    borderWidth: StyleSheet.hairlineWidth,
    paddingHorizontal: 12,
    paddingVertical: 7,
  },
  pillText: { fontSize: 13, fontVariant: ["tabular-nums"] },
  recordingDot: { width: 8, height: 8, borderRadius: 4 },
  fab: {
    width: 38,
    height: 38,
    borderRadius: 19,
    borderWidth: StyleSheet.hairlineWidth,
    alignItems: "center",
    justifyContent: "center",
  },
});

// The home screen and the app's signature interaction: a blank page you can
// type on immediately. Swiping up files the page away (the note slides off the
// top) and a fresh blank page is ready underneath — same gesture as the
// original app. Notes land in Feed via the desktop-compatible core.

import { useNavigation, useRoute } from "@react-navigation/native";
import type { RouteProp } from "@react-navigation/native";
import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  Keyboard,
  StyleSheet,
  TextInput,
  useWindowDimensions,
  View,
} from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import * as core from "@typenotes/mobile-core/core-api";

import { CaptureSession } from "../lib/capture";
import type { RootStackParamList } from "../navigation";
import { useNotesStore } from "../state/notes-store";
import { useTheme } from "../theme";
import { DictationButton } from "../ui/dictation-button";
import { ToolbarButton } from "../ui/toolbar-button";

const SWIPE_DISTANCE = 90;
const SWIPE_VELOCITY = -900;

export const CaptureScreen = () => {
  const theme = useTheme();
  const insets = useSafeAreaInsets();
  const navigation =
    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
  const { height } = useWindowDimensions();

  const [text, setText] = useState("");
  const [pageKey, setPageKey] = useState(0);
  const [iconsVisible, setIconsVisible] = useState(true);
  const [recordingActive, setRecordingActive] = useState(false);
  const iconsOpacity = useSharedValue(1);
  const inputRef = useRef<TextInput>(null);

  const session = useMemo(
    () =>
      new CaptureSession({
        createNote: async (content) => (await core.createNote({ content })).path,
        writeNote: core.writeNote,
        deleteNote: (path) => core.deleteItems([path]),
      }),
    []
  );

  // Flush the draft when the screen loses focus (navigation away).
  useEffect(
    () => navigation.addListener("blur", () => void session.flush()),
    [navigation, session]
  );

  // When the menu's swipe pushed this page with animation:none (its preview
  // overlay already played the transition), the flag must flip back so the
  // later pop / back swipe animates natively. Clearing it on mount is too
  // early: options re-evaluate to animation:"default" before the native push
  // has run, and the push then visibly replays with a slide. Wait for the
  // push transition to actually finish (plus a timeout fallback in case
  // animation:none emits no transition events).
  const route = useRoute<RouteProp<RootStackParamList, "Capture">>();
  useEffect(() => {
    if (!route.params?.instant) {
      return;
    }
    const clear = () => navigation.setParams({ instant: undefined });
    const unsubscribe = navigation.addListener("transitionEnd", (event) => {
      if (!event.data.closing) {
        clear();
      }
    });
    const fallback = setTimeout(clear, 600);
    return () => {
      unsubscribe();
      clearTimeout(fallback);
    };
  }, [navigation, route.params?.instant]);

  const translateY = useSharedValue(0);

  // Wrap Keyboard.dismiss so the worklet captures this plain closure rather
  // than the bare method — passing Keyboard.dismiss straight to runOnJS makes
  // worklets try to copy its owner (KeyboardImpl), which it can't serialize.
  const dismissKeyboard = () => Keyboard.dismiss();

  const commitPage = () => {
    void session.commit().then((path) => {
      if (path) {
        void useNotesStore.getState().refresh();
      }
    });
    // Remount the input so the new blank page appears with no text flash.
    setText("");
    setPageKey((key) => key + 1);
    translateY.value = 0;
    showIcons();
  };

  const showIcons = () => {
    setIconsVisible(true);
    iconsOpacity.value = withTiming(1, { duration: 180 });
  };

  const hideIcons = () => {
    setIconsVisible(false);
    iconsOpacity.value = withTiming(0, { duration: 180 });
  };

  // A clear downward drag tucks the keyboard away (the input regains it on
  // the next tap). Runs alongside the swipe-up gesture, which claims only
  // upward drags.
  const dismissKeyboardPan = Gesture.Pan()
    .activeOffsetY(24)
    .failOffsetY(-12)
    .onStart(() => {
      runOnJS(dismissKeyboard)();
    });

  const pan = Gesture.Pan()
    // Only claim clearly-upward drags; leave taps and downward scrolling to
    // the text input, and mostly-horizontal drags to the navigator's
    // full-screen back swipe (Capture screen options in App.tsx). The ±48
    // fail zone is deliberately wider than the -24 activation so a fast
    // diagonal swipe-up still files the page.
    .activeOffsetY([-24, Number.MAX_SAFE_INTEGER])
    .failOffsetX([-48, 48])
    .failOffsetY(12)
    .onUpdate((event) => {
      translateY.value = Math.min(0, event.translationY);
    })
    .onEnd((event) => {
      const shouldCommit =
        event.translationY < -SWIPE_DISTANCE || event.velocityY < SWIPE_VELOCITY;
      if (shouldCommit) {
        translateY.value = withTiming(
          -height,
          { duration: 200 },
          (finished) => {
            if (finished) {
              runOnJS(commitPage)();
            }
          }
        );
      } else {
        translateY.value = withSpring(0, { damping: 20, stiffness: 300 });
      }
    });

  const pageStyle = useAnimatedStyle(() => ({
    transform: [{ translateY: translateY.value }],
  }));

  const toolbarStyle = useAnimatedStyle(() => ({
    opacity: iconsOpacity.value,
  }));

  const onChange = (value: string) => {
    setText(value);
    session.onChange(value);
    // Keep the page uncluttered while writing; tapping back into the text
    // brings the hamburger/mic buttons back. While a dictation is running the
    // stop button must stay reachable, so nothing fades.
    if (iconsVisible && !recordingActive) {
      hideIcons();
    }
  };

  return (
    <View style={[styles.root, { backgroundColor: theme.colors.background }]}>
      <GestureDetector gesture={Gesture.Race(pan, dismissKeyboardPan)}>
        <Animated.View
          style={[
            styles.page,
            { backgroundColor: theme.colors.background, paddingTop: insets.top + 12 },
            pageStyle,
          ]}
        >
          <TextInput
            key={pageKey}
            ref={inputRef}
            style={[styles.input, { color: theme.colors.text }]}
            value={text}
            onChangeText={onChange}
            onPressIn={showIcons}
            placeholder="Start typing…"
            placeholderTextColor={theme.colors.secondaryText}
            multiline
            scrollEnabled
            textAlignVertical="top"
            keyboardAppearance={theme.dark ? "dark" : "light"}
          />
          {/* "swipe up for a new page" hint hidden per feedback — the gesture
              still works, we just don't want to show the label. */}
        </Animated.View>
      </GestureDetector>

      <Animated.View
        pointerEvents={iconsVisible ? "auto" : "none"}
        style={[styles.toolbarLeft, { top: insets.top + 8 }, toolbarStyle]}
      >
        <ToolbarButton
          icon="menu-outline"
          // popTo, not navigate: the menu is the stack root below this
          // screen, and v7 navigate would push a second Menu on top (sliding
          // in from the right) instead of popping back to it.
          onPress={() => navigation.popTo("Menu")}
        />
      </Animated.View>
      <Animated.View
        pointerEvents={iconsVisible ? "auto" : "none"}
        style={[styles.fab, { bottom: insets.bottom + 24 }, toolbarStyle]}
      >
        <DictationButton onRecordingChange={setRecordingActive} />
      </Animated.View>
    </View>
  );
};

const styles = StyleSheet.create({
  root: { flex: 1 },
  page: { flex: 1, paddingHorizontal: 20 },
  input: {
    flex: 1,
    fontSize: 17,
    lineHeight: 26,
    paddingTop: 44,
  },
  fab: {
    position: "absolute",
    right: 16,
    alignItems: "flex-end",
  },
  toolbarLeft: {
    position: "absolute",
    left: 16,
    flexDirection: "row",
  },
});

input.old_string:
fab: {
  position: "absolute",
  right: 16,
  alignItems: "flex-end",
},

input.new_string:
fab: {
  position: "absolute",
  right: 20,
  alignItems: "flex-end",
},

toolUseResult.oldString:
fab: {
  position: "absolute",
  right: 16,
  alignItems: "flex-end",
},

toolUseResult.newString:
fab: {
  position: "absolute",
  right: 20,
  alignItems: "flex-end",
},

