1	// The home screen and the app's signature interaction: a blank page you can
2	// type on immediately. Swiping up files the page away (the note slides off the
3	// top) and a fresh blank page is ready underneath — same gesture as the
4	// original app. Notes land in Feed via the desktop-compatible core.
5	
6	import { useNavigation, useRoute } from "@react-navigation/native";
7	import type { RouteProp } from "@react-navigation/native";
8	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
9	import { useEffect, useMemo, useRef, useState } from "react";
10	import {
11	  Keyboard,
12	  StyleSheet,
13	  TextInput,
14	  useWindowDimensions,
15	  View,
16	} from "react-native";
17	import { Gesture, GestureDetector } from "react-native-gesture-handler";
18	import Animated, {
19	  runOnJS,
20	  useAnimatedStyle,
21	  useSharedValue,
22	  withSpring,
23	  withTiming,
24	} from "react-native-reanimated";
25	import { useSafeAreaInsets } from "react-native-safe-area-context";
26	
27	import * as core from "@typenotes/mobile-core/core-api";
28	
29	import { CaptureSession } from "../lib/capture";
30	import type { RootStackParamList } from "../navigation";
31	import { useNotesStore } from "../state/notes-store";
32	import { useTheme } from "../theme";
33	import { DictationButton } from "../ui/dictation-button";
34	import { ToolbarButton } from "../ui/toolbar-button";
35	
36	const SWIPE_DISTANCE = 90;
37	const SWIPE_VELOCITY = -900;
38	
39	export const CaptureScreen = () => {
40	  const theme = useTheme();
41	  const insets = useSafeAreaInsets();
42	  const navigation =
43	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
44	  const { height } = useWindowDimensions();
45	
46	  const [text, setText] = useState("");
47	  const [pageKey, setPageKey] = useState(0);
48	  const [iconsVisible, setIconsVisible] = useState(true);
49	  const [recordingActive, setRecordingActive] = useState(false);
50	  const iconsOpacity = useSharedValue(1);
51	  const inputRef = useRef<TextInput>(null);
52	
53	  const session = useMemo(
54	    () =>
55	      new CaptureSession({
56	        createNote: async (content) => (await core.createNote({ content })).path,
57	        writeNote: core.writeNote,
58	        deleteNote: (path) => core.deleteItems([path]),
59	      }),
60	    []
61	  );
62	
63	  // Flush the draft when the screen loses focus (navigation away).
64	  useEffect(
65	    () => navigation.addListener("blur", () => void session.flush()),
66	    [navigation, session]
67	  );
68	
69	  // When the menu's swipe pushed this page with animation:none (its preview
70	  // overlay already played the transition), the flag must flip back so the
71	  // later pop / back swipe animates natively. Clearing it on mount is too
72	  // early: options re-evaluate to animation:"default" before the native push
73	  // has run, and the push then visibly replays with a slide. Wait for the
74	  // push transition to actually finish (plus a timeout fallback in case
75	  // animation:none emits no transition events).
76	  const route = useRoute<RouteProp<RootStackParamList, "Capture">>();
77	  useEffect(() => {
78	    if (!route.params?.instant) {
79	      return;
80	    }
81	    const clear = () => navigation.setParams({ instant: undefined });
82	    const unsubscribe = navigation.addListener("transitionEnd", (event) => {
83	      if (!event.data.closing) {
84	        clear();
85	      }
86	    });
87	    const fallback = setTimeout(clear, 600);
88	    return () => {
89	      unsubscribe();
90	      clearTimeout(fallback);
91	    };
92	  }, [navigation, route.params?.instant]);
93	
94	  const translateY = useSharedValue(0);
95	
96	  // Wrap Keyboard.dismiss so the worklet captures this plain closure rather
97	  // than the bare method — passing Keyboard.dismiss straight to runOnJS makes
98	  // worklets try to copy its owner (KeyboardImpl), which it can't serialize.
99	  const dismissKeyboard = () => Keyboard.dismiss();
100	
101	  const commitPage = () => {
102	    void session.commit().then((path) => {
103	      if (path) {
104	        void useNotesStore.getState().refresh();
105	      }
106	    });
107	    // Remount the input so the new blank page appears with no text flash.
108	    setText("");
109	    setPageKey((key) => key + 1);
110	    translateY.value = 0;
111	    showIcons();
112	  };
113	
114	  const showIcons = () => {
115	    setIconsVisible(true);
116	    iconsOpacity.value = withTiming(1, { duration: 180 });
117	  };
118	
119	  const hideIcons = () => {
120	    setIconsVisible(false);
121	    iconsOpacity.value = withTiming(0, { duration: 180 });
122	  };
123	
124	  // A clear downward drag tucks the keyboard away (the input regains it on
125	  // the next tap). Runs alongside the swipe-up gesture, which claims only
126	  // upward drags.
127	  const dismissKeyboardPan = Gesture.Pan()
128	    .activeOffsetY(24)
129	    .failOffsetY(-12)
130	    .onStart(() => {
131	      runOnJS(dismissKeyboard)();
132	    });
133	
134	  // Conceptually the sync screen sits to the RIGHT of the capture page (the
135	  // menu is to the left): a clearly-leftward drag pushes it. Rightward drags
136	  // stay with the native back swipe, vertical ones with the page gestures.
137	  // The keyboard is dismissed first — the capture input stays mounted (and
138	  // focused) beneath the pushed screen and would otherwise keep it up.
139	  const openSync = () => {
140	    Keyboard.dismiss();
141	    navigation.navigate("Sync");
142	  };
143	  const swipeToSync = Gesture.Pan()
144	    .activeOffsetX(-24)
145	    .failOffsetX(24)
146	    .failOffsetY([-24, 24])
147	    .onStart(() => {
148	      runOnJS(openSync)();
149	    });
150	
151	  const pan = Gesture.Pan()
152	    // Only claim clearly-upward drags; leave taps and downward scrolling to
153	    // the text input, and mostly-horizontal drags to the navigator's
154	    // full-screen back swipe (Capture screen options in App.tsx). The ±48
155	    // fail zone is deliberately wider than the -24 activation so a fast
156	    // diagonal swipe-up still files the page.
157	    .activeOffsetY([-24, Number.MAX_SAFE_INTEGER])
158	    .failOffsetX([-48, 48])
159	    .failOffsetY(12)
160	    .onUpdate((event) => {
161	      translateY.value = Math.min(0, event.translationY);
162	    })
163	    .onEnd((event) => {
164	      const shouldCommit =
165	        event.translationY < -SWIPE_DISTANCE || event.velocityY < SWIPE_VELOCITY;
166	      if (shouldCommit) {
167	        translateY.value = withTiming(
168	          -height,
169	          { duration: 200 },
170	          (finished) => {
171	            if (finished) {
172	              runOnJS(commitPage)();
173	            }
174	          }
175	        );
176	      } else {
177	        translateY.value = withSpring(0, { damping: 20, stiffness: 300 });
178	      }
179	    });
180	
181	  const pageStyle = useAnimatedStyle(() => ({
182	    transform: [{ translateY: translateY.value }],
183	  }));
184	
185	  const toolbarStyle = useAnimatedStyle(() => ({
186	    opacity: iconsOpacity.value,
187	  }));
188	
189	  const onChange = (value: string) => {
190	    setText(value);
191	    session.onChange(value);
192	    // Keep the page uncluttered while writing; tapping back into the text
193	    // brings the hamburger/mic buttons back. While a dictation is running the
194	    // stop button must stay reachable, so nothing fades.
195	    if (iconsVisible && !recordingActive) {
196	      hideIcons();
197	    }
198	  };
199	
200	  return (
201	    <View style={[styles.root, { backgroundColor: theme.colors.background }]}>
202	      <GestureDetector gesture={Gesture.Race(pan, dismissKeyboardPan, swipeToSync)}>
203	        <Animated.View
204	          style={[
205	            styles.page,
206	            { backgroundColor: theme.colors.background, paddingTop: insets.top + 12 },
207	            pageStyle,
208	          ]}
209	        >
210	          <TextInput
211	            key={pageKey}
212	            ref={inputRef}
213	            style={[styles.input, { color: theme.colors.text }]}
214	            value={text}
215	            onChangeText={onChange}
216	            onPressIn={showIcons}
217	            placeholder="Start typing…"
218	            placeholderTextColor={theme.colors.secondaryText}
219	            multiline
220	            scrollEnabled
221	            textAlignVertical="top"
222	            keyboardAppearance={theme.dark ? "dark" : "light"}
223	          />
224	          {/* "swipe up for a new page" hint hidden per feedback — the gesture
225	              still works, we just don't want to show the label. */}
226	        </Animated.View>
227	      </GestureDetector>
228	
229	      <Animated.View
230	        pointerEvents={iconsVisible ? "auto" : "none"}
231	        style={[styles.toolbarLeft, { top: insets.top + 8 }, toolbarStyle]}
232	      >
233	        <ToolbarButton
234	          icon="menu-outline"
235	          // popTo, not navigate: the menu is the stack root below this
236	          // screen, and v7 navigate would push a second Menu on top (sliding
237	          // in from the right) instead of popping back to it.
238	          onPress={() => navigation.popTo("Menu")}
239	        />
240	      </Animated.View>
241	      <Animated.View
242	        pointerEvents={iconsVisible ? "auto" : "none"}
243	        style={[styles.fab, { bottom: insets.bottom + 36 }, toolbarStyle]}
244	      >
245	        <DictationButton onRecordingChange={setRecordingActive} />
246	      </Animated.View>
247	    </View>
248	  );
249	};
250	
251	const styles = StyleSheet.create({
252	  root: { flex: 1 },
253	  page: { flex: 1, paddingHorizontal: 20 },
254	  input: {
255	    flex: 1,
256	    fontSize: 17,
257	    lineHeight: 26,
258	    paddingTop: 44,
259	  },
260	  fab: {
261	    position: "absolute",
262	    right: 32,
263	    alignItems: "flex-end",
264	  },
265	  toolbarLeft: {
266	    position: "absolute",
267	    left: 20,
268	    flexDirection: "row",
269	  },
270	});
